"""Check each monitor against the literal transition rules in the contract."""
import importlib.util
import itertools
import random

spec = importlib.util.spec_from_file_location("mainmod", "/workspace/submission/main.py")
mod = importlib.util.module_from_spec(spec)
spec.loader.exec_module(mod)


def literal_match(p, m, state, tok):
    if state < m:
        return state + 1 if tok == p[state] else m + 1
    return m + 1


def literal_startswith(p, m, state, tok):
    if state < m:
        return state + 1 if tok == p[state] else m + 1
    return m


def literal_endswith(p, m, state, tok):
    best = 0
    for j in range(0, m + 1):
        if len(p[:j]) <= len(p[:state] + [tok]):
            if p[:j] == (p[:state] + [tok])[len(p[:state] + [tok]) - len(p[:j]):]:
                best = j
    return best


def literal_contains(p, m, state, tok):
    if state >= m:
        return m
    return literal_endswith(p, m, state, tok)


rng = random.Random(3)
bad = 0
for trial in range(400):
    alphabet = ["a", "b", "c"]
    m = rng.randint(0, 5)
    p = [rng.choice(alphabet) for _ in range(m)]
    for op, literal in (("match", literal_match), ("startswith", literal_startswith),
                        ("endswith", literal_endswith), ("contains", literal_contains)):
        nstates, table, true_states = mod._monitor(op, list(p), alphabet)
        expected_states = m + 2 if op in ("match", "startswith") else m + 1
        if nstates != expected_states:
            print("BAD state count", op, m, nstates, expected_states)
            bad += 1
        for state in range(nstates):
            for si, tok in enumerate(alphabet):
                got = table[state][si]
                want = literal(p, m, state, tok)
                if got != want:
                    print("BAD", op, "p=", p, "state", state, "tok", tok, "got", got, "want", want)
                    bad += 1
        # truth values
        for state in range(nstates):
            want_true = (state == m)
            if (state in true_states) != want_true:
                print("BAD truth", op, p, state)
                bad += 1
print("monitor rule violations:", bad)
PYEOF
